address":"0x6a0dc3f5a77058e37390cecdb1a520acf2cbdaa5","profile_id":"P098","avatar_url":"https://gateway.pinata.cloud/ipfs/Qme1ye4CHkySQbUQxPcmwLXePW7argAiNZ9AsmygABCNu9","avatar_ipfs_hash":"Qme1ye4CHkySQbUQxPcmwLXePW7argAiNZ9AsmygABCNu9","banner_url":"https://gateway.pinata.cloud/ipfs/Qme1ye4CHkySQbUQxPcmwLXePW7argAiNZ9AsmygABCNu9","banner_ipfs_hash":"Qme1ye4CHkySQbUQxPcmwLXePW7argAiNZ9AsmygABCNu9"},{"wallet_address":"0x329543d281b62608f35dca28f3a235457721b093","profile_id":"P099","avatar_url":"https://gateway.pinata.cloud/ipfs/Qme1ye4CHkySQbUQxPcmwLXePW7argAiNZ9AsmygABCNu9","avatar_ipfs_hash":"Qme1ye4CHkySQbUQxPcmwLXePW7argAiNZ9AsmygABCNu9","banner_url":"https://gateway.pinata.cloud/ipfs/Qme1ye4CHkySQbUQxPcmwLXePW7argAiNZ9AsmygABCNu9","banner_ipfs_hash":"Qme1ye4CHkySQbUQxPcmwLXePW7argAiNZ9AsmygABCNu9"},{"wallet_address":"0x3931d00663e24b20d7a8ec3bd1917ca7efc85f5c","profile_id":"P100","avatar_url":"https://gateway.pinata.cloud/ipfs/Qme1ye4CHkySQbUQxPcmwLXePW7argAiNZ9AsmygABCNu9","avatar_ipfs_hash":"Qme1ye4CHkySQbUQxPcmwLXePW7argAiNZ9AsmygABCNu9","banner_url":"https://gateway.pinata.cloud/ipfs/Qme1ye4CHkySQbUQxPcmwLXePW7argAiNZ9AsmygABCNu9","banner_ipfs_hash":"Qme1ye4CHkySQbUQxPcmwLXePW7argAiNZ9AsmygABCNu9"}]$media$::jsonb;
begin
  create temporary table tmp_v35_seed_profile_media (
    wallet_address text primary key,
    profile_id text not null,
    avatar_url text not null,
    avatar_ipfs_hash text not null,
    banner_url text not null,
    banner_ipfs_hash text not null
  ) on commit drop;

  insert into tmp_v35_seed_profile_media (
    wallet_address,
    profile_id,
    avatar_url,
    avatar_ipfs_hash,
    banner_url,
    banner_ipfs_hash
  )
  select
    lower(item ->> 'wallet_address'),
    item ->> 'profile_id',
    item ->> 'avatar_url',
    item ->> 'avatar_ipfs_hash',
    item ->> 'banner_url',
    item ->> 'banner_ipfs_hash'
  from jsonb_array_elements(payload) item;

  update public.profiles profiles
  set
    avatar_url = media.avatar_url,
    banner_url = media.banner_url,
    updated_at = now()
  from tmp_v35_seed_profile_media media
  where profiles.wallet_address = media.wallet_address;

  update public.profile_story_documents story
  set
    story_document = story.story_document || jsonb_build_object(
      'seedProfileMetadata',
      coalesce(story.story_document -> 'seedProfileMetadata', '{}'::jsonb) || jsonb_build_object(
        'media_source', 'pinata_ipfs',
        'media_manifest', 'supabase/audit/v3_5_beta_seed_profile_media_ipfs_manifest.json',
        'avatar_url', media.avatar_url,
        'avatar_ipfs_hash', media.avatar_ipfs_hash,
        'banner_url', media.banner_url,
        'banner_ipfs_hash', media.banner_ipfs_hash
      )
    ),
    updated_at = now()
  from public.profiles profiles
  join tmp_v35_seed_profile_media media
    on media.wallet_address = profiles.wallet_address
  where story.user_id = profiles.id
    and story.story_document -> 'seedProfileMetadata' ->> 'seed_batch' = 'v3.5-beta-seed-profiles-001';

  update public.user_preferences prefs
  set
    ui_preferences = jsonb_set(
      jsonb_set(
        coalesce(prefs.ui_preferences, '{}'::jsonb),
        '{seed_profile_metadata}',
        coalesce(prefs.ui_preferences -> 'seed_profile_metadata', '{}'::jsonb) || jsonb_build_object(
        'media_source', 'pinata_ipfs',
        'media_manifest', 'supabase/audit/v3_5_beta_seed_profile_media_ipfs_manifest.json',
        'avatar_url', media.avatar_url,
        'avatar_ipfs_hash', media.avatar_ipfs_hash,
        'banner_url', media.banner_url,
        'banner_ipfs_hash', media.banner_ipfs_hash
      ),
        true
      ),
      '{story_document,seedProfileMetadata}',
      coalesce(prefs.ui_preferences #> '{story_document,seedProfileMetadata}', '{}'::jsonb) || jsonb_build_object(
        'media_source', 'pinata_ipfs',
        'media_manifest', 'supabase/audit/v3_5_beta_seed_profile_media_ipfs_manifest.json',
        'avatar_url', media.avatar_url,
        'avatar_ipfs_hash', media.avatar_ipfs_hash,
        'banner_url', media.banner_url,
        'banner_ipfs_hash', media.banner_ipfs_hash
      ),
      true
    ),
    updated_at = now()
  from public.profiles profiles
  join tmp_v35_seed_profile_media media
    on media.wallet_address = profiles.wallet_address
  where prefs.user_id = profiles.id;

  perform public.refresh_marketplace_profile_browse_index_v1();
end $$;
